946	func rejectLegacyProviderReasoningKeys(data []byte) error {
947		var raw struct {
948			Providers map[string]map[string]any `yaml:"providers"`
949		}
950		if err := yaml.Unmarshal(data, &raw); err != nil {
951			return err
952		}
953		for name, provider := range raw.Providers {
954			if _, ok := provider["flavor"]; ok {
955				return fmt.Errorf("provider %q: flavor is no longer supported; use a concrete provider type", name)
956			}
957			for _, key := range []string{"thinking" + "_level", "thinking" + "_budget"} {
958				if _, ok := provider[key]; ok {
959					return fmt.Errorf("provider %q: use reasoning instead of %s", name, key)
960				}
961			}
962		}
963		return nil
964	}
