1	// Command fizeau-probe-reasoning measures which reasoning wire knob a live
2	// endpoint actually honors. It sends a fixed 6-row matrix of chat-completion
3	// requests (off / low / medium / high / 4096 / 16384) and prints a markdown
4	// table with per-row measurements and a verdict line recommending the correct
5	// reasoning_wire catalog value.
6	package main
7	
8	import (
9		"bytes"
10		"context"
11		"crypto/sha256"
12		"encoding/json"
13		"flag"
14		"fmt"
15		"io"
16		"math"
17		"net/http"
18		"os"
19		"path/filepath"
20		"regexp"
21		"strings"
22		"time"
23	
24		"github.com/easel/fizeau/internal/benchmark/profile"
25		reasoning "github.com/easel/fizeau/internal/reasoning"
26	)
27	
28	const (
29		probePrompt    = "Briefly explain what 2+2 equals."
30		probeMaxToks   = 512 // enough for an answer + some thinking
31		requestTimeout = 5 * time.Minute
32	)
33	
34	// wireFormat enumerates the provider-side reasoning wire shapes the probe can emit.
35	type wireFormat string
36	
37	const (
38		wireOpenRouter  wireFormat = "openrouter"   // reasoning: {effort|max_tokens}
39		wireQwen        wireFormat = "qwen"         // enable_thinking + thinking_budget
40		wireThinkingMap wireFormat = "thinking_map" // thinking: {type, budget_tokens}
41	)
42	
43	// probeCase is one row in the measurement matrix.
44	type probeCase struct {
45		Label  string
46		Policy reasoning.Policy
47	}
48	
49	// probeMatrix is the fixed set of reasoning requests to send.
50	var probeMatrix = []probeCase{
51		{Label: "off", Policy: reasoning.Policy{Kind: reasoning.KindOff, Value: reasoning.ReasoningOff}},
52		{Label: "low", Policy: reasoning.Policy{Kind: reasoning.KindNamed, Value: reasoning.ReasoningLow}},
53		{Label: "medium", Policy: reasoning.Policy{Kind: reasoning.KindNamed, Value: reasoning.ReasoningMedium}},
54		{Label: "high", Policy: reasoning.Policy{Kind: reasoning.KindNamed, Value: reasoning.ReasoningHigh}},
55		{Label: "4096", Policy: reasoning.Policy{Kind: reasoning.KindTokens, Value: reasoning.ReasoningTokens(4096), Tokens: 4096}},
56		{Label: "16384", Policy: reasoning.Policy{Kind: reasoning.KindTokens, Value: reasoning.ReasoningTokens(16384), Tokens: 16384}},
57	}
58	
59	// probeResult captures the measured outcome for one matrix row.
60	type probeResult struct {
61		Label         string
62		WireBody      json.RawMessage // raw JSON sent to the endpoint
63		FinishReason  string
64		ReasoningToks int
65		WallTime      time.Duration
66		ThinkHash     string // SHA-256 hex prefix of <think> block content, or ""
67		ResponseBody  json.RawMessage
68		Error         string
69	}
