71	// probeConfig holds the resolved endpoint / provider parameters.
72	type probeConfig struct {
73		baseURL   string
74		apiKey    string
75		model     string
76		format    wireFormat
77		profileID string
78	}
79	
80	// verdict is the analysis result over all matrix rows.
81	type verdict struct {
82		Wire        string // recommended catalog reasoning_wire value
83		Explanation string
84		AllZero     bool
85		NamedFlat   bool // low/medium/high produce same token count
86		TokensWork  bool // 4096 vs 16384 differ proportionally
87	}
