89	// probeReport bundles results + verdict for serialisation.
90	type probeReport struct {
91		ProfileID  string        `json:"profile_id"`
92		Model      string        `json:"model"`
93		BaseURL    string        `json:"base_url"`
94		WireFormat string        `json:"wire_format"`
95		Timestamp  string        `json:"timestamp"`
96		Results    []probeResult `json:"results"`
97		Verdict    verdict       `json:"verdict"`
98	}
