100	func main() {
101		os.Exit(run(os.Args[1:]))
102	}
103	
104	func run(args []string) int {
105		fs := flag.NewFlagSet("fizeau-probe-reasoning", flag.ContinueOnError)
106		fs.SetOutput(os.Stderr)
107	
108		profilePath := fs.String("profile", "", "Path to fizeau benchmark profile YAML")
109		providerFlag := fs.String("provider", "", "Provider type override (openrouter|lmstudio|vllm|etc.)")
110		modelFlag := fs.String("model", "", "Model ID override")
111		baseURLFlag := fs.String("base-url", "", "API base URL override")
112		apiKeyFlag := fs.String("api-key", "", "API key (overrides api_key_env from profile)")
113		jsonOut := fs.Bool("json", false, "Emit machine-readable JSON instead of markdown")
114		artifactDir := fs.String("artifact-dir", "", "Directory for per-row audit files (default: /tmp/probe-<ts>/)")
115	
116		if err := fs.Parse(args); err != nil {
117			return 2
118		}
119	
120		cfg, err := resolveConfig(*profilePath, *providerFlag, *modelFlag, *baseURLFlag, *apiKeyFlag)
121		if err != nil {
122			fmt.Fprintf(os.Stderr, "error: %v\n", err)
123			fs.Usage()
124			return 2
125		}
126	
127		artDir := *artifactDir
128		if artDir == "" {
129			artDir = filepath.Join("/tmp", fmt.Sprintf("probe-%s", time.Now().UTC().Format("20060102T150405Z")))
130		}
131		if err := os.MkdirAll(artDir, 0o750); err != nil {
132			fmt.Fprintf(os.Stderr, "error: create artifact dir %s: %v\n", artDir, err)
133			return 1
134		}
135	
136		fmt.Fprintf(os.Stderr, "probe: model=%s base_url=%s wire=%s\n", cfg.model, cfg.baseURL, cfg.format)
137		fmt.Fprintf(os.Stderr, "probe: artifacts → %s\n", artDir)
138	
139		results := runMatrix(cfg, artDir)
140		v := computeVerdict(results)
141	
142		report := probeReport{
143			ProfileID:  cfg.profileID,
144			Model:      cfg.model,
145			BaseURL:    cfg.baseURL,
146			WireFormat: string(cfg.format),
147			Timestamp:  time.Now().UTC().Format(time.RFC3339),
148			Results:    results,
149			Verdict:    v,
150		}
151	
152		// Write a summary artifact.
153		writeArtifact(artDir, "summary.json", mustMarshalIndent(report))
154	
155		if *jsonOut {
156			return outputJSON(report)
157		}
158		return outputMarkdown(report)
159	}
