161	// resolveConfig builds a probeConfig from a profile path or explicit flags.
162	func resolveConfig(profilePath, providerType, model, baseURL, apiKey string) (probeConfig, error) {
163		if profilePath != "" {
164			p, err := profile.Load(profilePath)
165			if err != nil {
166				return probeConfig{}, fmt.Errorf("load profile: %w", err)
167			}
168			// Explicit flag overrides win over profile values.
169			if model == "" {
170				model = p.Provider.Model
171			}
172			if baseURL == "" {
173				baseURL = p.Provider.BaseURL
174			}
175			if providerType == "" {
176				providerType = string(p.Provider.Type)
177			}
178			if apiKey == "" && p.Provider.APIKeyEnv != "" {
179				apiKey = os.Getenv(p.Provider.APIKeyEnv)
180			}
181			cfg := probeConfig{
182				baseURL:   baseURL,
183				apiKey:    apiKey,
184				model:     model,
185				format:    wireFormatFor(providerType),
186				profileID: p.ID,
187			}
188			return cfg, cfg.validate()
189		}
190	
191		// Flags-only mode.
192		cfg := probeConfig{
193			baseURL: baseURL,
194			apiKey:  apiKey,
195			model:   model,
196			format:  wireFormatFor(providerType),
197		}
198		return cfg, cfg.validate()
199	}
200	
201	func (c probeConfig) validate() error {
202		if c.baseURL == "" {
203			return fmt.Errorf("--base-url (or profile.provider.base_url) is required")
204		}
205		if c.model == "" {
206			return fmt.Errorf("--model (or profile.provider.model) is required")
207		}
208		return nil
209	}
