211	// wireFormatFor maps a profile provider type string to the correct wire format.
212	func wireFormatFor(providerType string) wireFormat {
213		switch strings.ToLower(providerType) {
214		case "openrouter":
215			return wireOpenRouter
216		case "ds4", "anthropic":
217			return wireThinkingMap
218		default:
219			// lmstudio, vllm, llama-server, omlx, ollama, rapid-mlx, openai-compat use Qwen wire.
220			return wireQwen
221		}
222	}
223	
224	// runMatrix sends all probeMatrix rows sequentially and returns the results.
225	func runMatrix(cfg probeConfig, artDir string) []probeResult {
226		results := make([]probeResult, 0, len(probeMatrix))
227		for _, pc := range probeMatrix {
228			fmt.Fprintf(os.Stderr, "probe: sending reasoning=%s ...\n", pc.Label)
229			r := sendProbe(cfg, pc)
230			writeArtifacts(artDir, pc.Label, r)
231			results = append(results, r)
232		}
233		return results
234	}
