236	// sendProbe executes one chat-completion request and returns the measured result.
237	func sendProbe(cfg probeConfig, pc probeCase) probeResult {
238		r := probeResult{Label: pc.Label}
239	
240		body, err := buildWireBody(cfg, pc.Policy)
241		if err != nil {
242			r.Error = fmt.Sprintf("build wire body: %v", err)
243			return r
244		}
245		r.WireBody = body
246	
247		ctx, cancel := context.WithTimeout(context.Background(), requestTimeout)
248		defer cancel()
249	
250		endpoint := strings.TrimRight(cfg.baseURL, "/") + "/chat/completions"
251		req, err := http.NewRequestWithContext(ctx, http.MethodPost, endpoint, bytes.NewReader(body))
252		if err != nil {
253			r.Error = fmt.Sprintf("build request: %v", err)
254			return r
255		}
256		req.Header.Set("Content-Type", "application/json")
257		req.Header.Set("Accept", "application/json")
258		if cfg.apiKey != "" {
259			req.Header.Set("Authorization", "Bearer "+cfg.apiKey)
260		}
261	
262		start := time.Now()
263		resp, err := http.DefaultClient.Do(req)
264		r.WallTime = time.Since(start)
265		if err != nil {
266			r.Error = fmt.Sprintf("http: %v", err)
267			return r
268		}
269		defer resp.Body.Close()
270	
271		respBytes, err := io.ReadAll(resp.Body)
272		if err != nil {
273			r.Error = fmt.Sprintf("read response: %v", err)
274			return r
275		}
276		r.ResponseBody = json.RawMessage(respBytes)
277	
278		if resp.StatusCode != http.StatusOK {
279			r.Error = fmt.Sprintf("http %d: %s", resp.StatusCode, truncate(string(respBytes), 200))
280			return r
281		}
282	
283		parseResponse(respBytes, &r)
284		return r
285	}
286	
287	// buildWireBody constructs the chat-completion request JSON for a given policy
288	// and wire format.
289	func buildWireBody(cfg probeConfig, policy reasoning.Policy) (json.RawMessage, error) {
290		body := map[string]interface{}{
291			"model": cfg.model,
292			"messages": []map[string]string{
293				{"role": "user", "content": probePrompt},
294			},
295			"max_tokens": probeMaxToks,
296		}
297	
298		if err := addReasoningFields(body, cfg.format, policy); err != nil {
299			return nil, err
300		}
301	
302		out, err := json.MarshalIndent(body, "", "  ")
303		return json.RawMessage(out), err
304	}
305	
306	// addReasoningFields injects the wire-format-specific reasoning fields into the
307	// request body map. It is a pure function used both by sendProbe and tests.
308	func addReasoningFields(body map[string]interface{}, format wireFormat, policy reasoning.Policy) error {
309		switch format {
310		case wireOpenRouter:
311			return addOpenRouterFields(body, policy)
312		case wireQwen:
313			return addQwenFields(body, policy)
314		case wireThinkingMap:
315			return addThinkingMapFields(body, policy)
316		default:
317			return fmt.Errorf("unknown wire format %q", format)
318		}
319	}
320	
321	func addOpenRouterFields(body map[string]interface{}, policy reasoning.Policy) error {
322		switch policy.Kind {
323		case reasoning.KindOff:
324			body["reasoning"] = map[string]interface{}{"effort": "none"}
325		case reasoning.KindNamed:
326			effort := string(policy.Value)
327			switch effort {
328			case "minimal", "low", "medium", "high", "xhigh":
329			default:
330				return fmt.Errorf("unsupported OpenRouter effort %q", effort)
331			}
332			body["reasoning"] = map[string]interface{}{"effort": effort}
333		case reasoning.KindTokens:
334			body["reasoning"] = map[string]interface{}{"max_tokens": policy.Tokens}
335		default:
336			return fmt.Errorf("unsupported policy kind %q for openrouter wire", policy.Kind)
337		}
338		return nil
339	}
340	
341	func addQwenFields(body map[string]interface{}, policy reasoning.Policy) error {
342		if policy.Kind == reasoning.KindOff {
343			body["enable_thinking"] = false
344			body["thinking_budget"] = 0
345			return nil
346		}
347		budget, err := reasoning.BudgetFor(policy, nil, 0)
348		if err != nil {
349			return err
350		}
351		if budget <= 0 {
352			body["enable_thinking"] = false
353			body["thinking_budget"] = 0
354			return nil
355		}
356		body["enable_thinking"] = true
357		body["thinking_budget"] = budget
358		return nil
359	}
360	
361	func addThinkingMapFields(body map[string]interface{}, policy reasoning.Policy) error {
362		if policy.Kind == reasoning.KindOff {
363			// Some servers expect the field absent; others accept type=disabled.
364			// Send no field for off so we don't confuse non-thinking models.
365			return nil
366		}
367		budget, err := reasoning.BudgetFor(policy, nil, 0)
368		if err != nil {
369			return err
370		}
371		if budget <= 0 {
372			return nil
373		}
374		body["thinking"] = map[string]interface{}{
375			"type":          "enabled",
376			"budget_tokens": budget,
377		}
378		return nil
379	}
380	
381	var thinkRe = regexp.MustCompile(`(?s)<think>(.*?)</think>`)
382	
383	// parseResponse extracts finish_reason, reasoning_tokens, and <think> hash
384	// from a raw chat-completion response body.
385	func parseResponse(raw []byte, r *probeResult) {
386		var resp struct {
387			Choices []struct {
388				FinishReason string `json:"finish_reason"`
389				Message      struct {
390					Content string `json:"content"`
391				} `json:"message"`
392			} `json:"choices"`
393			Usage json.RawMessage `json:"usage"`
394		}
395		if err := json.Unmarshal(raw, &resp); err != nil {
396			r.Error = fmt.Sprintf("parse response json: %v", err)
397			return
398		}
399		if len(resp.Choices) > 0 {
400			r.FinishReason = resp.Choices[0].FinishReason
401			content := resp.Choices[0].Message.Content
402			if m := thinkRe.FindStringSubmatch(content); len(m) > 1 {
403				sum := sha256.Sum256([]byte(m[1]))
404				r.ThinkHash = fmt.Sprintf("%x", sum[:8])
405			}
406		}
407		if len(resp.Usage) > 0 {
408			r.ReasoningToks = extractReasoningTokens(string(resp.Usage))
409		}
410	}
411	
412	// extractReasoningTokens mirrors the same function in internal/sdk/openaicompat.
413	func extractReasoningTokens(rawUsageJSON string) int {
414		if rawUsageJSON == "" {
415			return 0
416		}
417		var raw struct {
418			CompletionTokensDetails struct {
419				ReasoningTokens int `json:"reasoning_tokens"`
420			} `json:"completion_tokens_details"`
421			ReasoningTokens *int `json:"reasoning_tokens,omitempty"`
422		}
423		if err := json.Unmarshal([]byte(rawUsageJSON), &raw); err != nil {
424			return 0
425		}
426		if raw.ReasoningTokens != nil && *raw.ReasoningTokens > 0 {
427			return *raw.ReasoningTokens
428		}
429		return raw.CompletionTokensDetails.ReasoningTokens
430	}
