432	// computeVerdict analyses the matrix results and returns a catalog recommendation.
433	func computeVerdict(results []probeResult) verdict {
434		toks := map[string]int{}
435		for _, r := range results {
436			toks[r.Label] = r.ReasoningToks
437		}
438	
439		// Edge: no reasoning tokens at all.
440		allZero := true
441		for _, r := range results {
442			if r.ReasoningToks > 0 {
443				allZero = false
444				break
445			}
446		}
447		if allZero {
448			return verdict{
449				Wire:        "none",
450				Explanation: "reasoning_tokens is 0 for every matrix row; the upstream endpoint is not performing any reasoning. Flag the model as reasoning_wire=none in the catalog.",
451				AllZero:     true,
452			}
453		}
454	
455		// Check whether named tiers (low/medium/high) are flat-mapped.
456		namedToks := []int{toks["low"], toks["medium"], toks["high"]}
457		namedFlat := allWithinPct(namedToks, 5)
458	
459		// Check whether token budgets (4096 vs 16384) produce proportionally different counts.
460		tok4096 := toks["4096"]
461		tok16384 := toks["16384"]
462		tokensWork := budgetsDifferProportionally(tok4096, tok16384, 4096, 16384, 20)
463	
464		switch {
465		case namedFlat && tokensWork:
466			return verdict{
467				Wire:        "tokens",
468				Explanation: "Named effort tiers (low/medium/high) produce the same reasoning_token count — they are flat-mapped upstream. Token budgets (4096 vs 16384) are honored. Use reasoning_wire=tokens in the catalog.",
469				NamedFlat:   true,
470				TokensWork:  true,
471			}
472		case namedFlat && !tokensWork:
473			return verdict{
474				Wire:        "tokens",
475				Explanation: "Named effort tiers are flat-mapped upstream. Token budget variation was not observed (possibly capped or not yet testable). Recommend reasoning_wire=tokens as the safer wire form.",
476				NamedFlat:   true,
477				TokensWork:  false,
478			}
479		case !namedFlat && tokensWork:
480			return verdict{
481				Wire:        "effort",
482				Explanation: "Both effort tiers and token budgets vary meaningfully. Either wire form works; defaulting to reasoning_wire=effort (the more natural caller form).",
483				NamedFlat:   false,
484				TokensWork:  true,
485			}
486		default:
487			return verdict{
488				Wire:        "effort",
489				Explanation: "Named tiers vary but token budgets do not show clear proportional scaling. Use reasoning_wire=effort; investigate reasoning_wire=tokens if token precision is needed.",
490				NamedFlat:   false,
491				TokensWork:  false,
492			}
493		}
494	}
495	
496	// allWithinPct returns true if all values in vs are within pct% of their mean.
497	func allWithinPct(vs []int, pct float64) bool {
498		if len(vs) == 0 {
499			return true
500		}
501		nonZero := 0
502		sum := 0
503		for _, v := range vs {
504			if v > 0 {
505				nonZero++
506				sum += v
507			}
508		}
509		if nonZero == 0 {
510			return true
511		}
512		mean := float64(sum) / float64(nonZero)
513		for _, v := range vs {
514			if v == 0 {
515				continue
516			}
517			if math.Abs(float64(v)-mean)/mean*100 > pct {
518				return false
519			}
520		}
521		return true
522	}
523	
524	// budgetsDifferProportionally returns true when the ratio of observed reasoning
525	// tokens for two different budgets is within tolerancePct% of the ratio of the
526	// requested budgets. E.g. budget 16384 should produce ~4x the tokens of 4096.
527	func budgetsDifferProportionally(toks1, toks2, budget1, budget2 int, tolerancePct float64) bool {
528		if toks1 <= 0 || toks2 <= 0 {
529			return false
530		}
531		expectedRatio := float64(budget2) / float64(budget1)
532		observedRatio := float64(toks2) / float64(toks1)
533		// Within tolerancePct% of expected ratio.
534		return math.Abs(observedRatio-expectedRatio)/expectedRatio*100 <= tolerancePct
535	}
