537	func outputMarkdown(report probeReport) int {
538		fmt.Printf("# fizeau-probe-reasoning\n\n")
539		fmt.Printf("**Profile:** %s  \n", report.ProfileID)
540		fmt.Printf("**Model:** `%s`  \n", report.Model)
541		fmt.Printf("**Endpoint:** `%s`  \n", report.BaseURL)
542		fmt.Printf("**Wire format:** `%s`  \n", report.WireFormat)
543		fmt.Printf("**Timestamp:** %s\n\n", report.Timestamp)
544	
545		fmt.Printf("| Reasoning | finish_reason | reasoning_tokens | wall_time | think_hash | error |\n")
546		fmt.Printf("|-----------|---------------|-----------------|-----------|------------|-------|\n")
547		for _, r := range report.Results {
548			errCol := r.Error
549			if errCol == "" {
550				errCol = "—"
551			}
552			thinkCol := r.ThinkHash
553			if thinkCol == "" {
554				thinkCol = "—"
