34	// wireFormat enumerates the provider-side reasoning wire shapes the probe can emit.
35	type wireFormat string
36	
37	const (
38		wireOpenRouter  wireFormat = "openrouter"   // reasoning: {effort|max_tokens}
39		wireQwen        wireFormat = "qwen"         // enable_thinking + thinking_budget
40		wireThinkingMap wireFormat = "thinking_map" // thinking: {type, budget_tokens}
41	)
