43	// probeCase is one row in the measurement matrix.
44	type probeCase struct {
45		Label  string
46		Policy reasoning.Policy
47	}
48	
49	// probeMatrix is the fixed set of reasoning requests to send.
50	var probeMatrix = []probeCase{
51		{Label: "off", Policy: reasoning.Policy{Kind: reasoning.KindOff, Value: reasoning.ReasoningOff}},
52		{Label: "low", Policy: reasoning.Policy{Kind: reasoning.KindNamed, Value: reasoning.ReasoningLow}},
53		{Label: "medium", Policy: reasoning.Policy{Kind: reasoning.KindNamed, Value: reasoning.ReasoningMedium}},
54		{Label: "high", Policy: reasoning.Policy{Kind: reasoning.KindNamed, Value: reasoning.ReasoningHigh}},
55		{Label: "4096", Policy: reasoning.Policy{Kind: reasoning.KindTokens, Value: reasoning.ReasoningTokens(4096), Tokens: 4096}},
56		{Label: "16384", Policy: reasoning.Policy{Kind: reasoning.KindTokens, Value: reasoning.ReasoningTokens(16384), Tokens: 16384}},
57	}
