224	// runMatrix sends all probeMatrix rows sequentially and returns the results.
225	func runMatrix(cfg probeConfig, artDir string) []probeResult {
226		results := make([]probeResult, 0, len(probeMatrix))
227		for _, pc := range probeMatrix {
228			fmt.Fprintf(os.Stderr, "probe: sending reasoning=%s ...\n", pc.Label)
