236	// sendProbe executes one chat-completion request and returns the measured result.
237	func sendProbe(cfg probeConfig, pc probeCase) probeResult {
238		r := probeResult{Label: pc.Label}
239	
240		body, err := buildWireBody(cfg, pc.Policy)
241		if err != nil {
242			r.Error = fmt.Sprintf("build wire body: %v", err)
243			return r
244		}
245		r.WireBody = body
246	
247		ctx, cancel := context.WithTimeout(context.Background(), requestTimeout)
248		defer cancel()
249	
250		endpoint := strings.TrimRight(cfg.baseURL, "/") + "/chat/completions"
251		req, err := http.NewRequestWithContext(ctx, http.MethodPost, endpoint, bytes.NewReader(body))
252		if err != nil {
253			r.Error = fmt.Sprintf("build request: %v", err)
254			return r
255		}
256		req.Header.Set("Content-Type", "application/json")
257		req.Header.Set("Accept", "application/json")
258		if cfg.apiKey != "" {
259			req.Header.Set("Authorization", "Bearer "+cfg.apiKey)
260		}
261	
262		start := time.Now()
263		resp, err := http.DefaultClient.Do(req)
264		r.WallTime = time.Since(start)
265		if err != nil {
266			r.Error = fmt.Sprintf("http: %v", err)
267			return r
268		}
269		defer resp.Body.Close()
270	
271		respBytes, err := io.ReadAll(resp.Body)
272		if err != nil {
273			r.Error = fmt.Sprintf("read response: %v", err)
274			return r
275		}
276		r.ResponseBody = json.RawMessage(respBytes)
277	
278		if resp.StatusCode != http.StatusOK {
279			r.Error = fmt.Sprintf("http %d: %s", resp.StatusCode, truncate(string(respBytes), 200))
280			return r
281		}
282	
283		parseResponse(respBytes, &r)
284		return r
285	}
