306	// addReasoningFields injects the wire-format-specific reasoning fields into the
307	// request body map. It is a pure function used both by sendProbe and tests.
308	func addReasoningFields(body map[string]interface{}, format wireFormat, policy reasoning.Policy) error {
309		switch format {
310		case wireOpenRouter:
311			return addOpenRouterFields(body, policy)
312		case wireQwen:
313			return addQwenFields(body, policy)
314		case wireThinkingMap:
315			return addThinkingMapFields(body, policy)
316		default:
317			return fmt.Errorf("unknown wire format %q", format)
318		}
