321	func addOpenRouterFields(body map[string]interface{}, policy reasoning.Policy) error {
322		switch policy.Kind {
323		case reasoning.KindOff:
324			body["reasoning"] = map[string]interface{}{"effort": "none"}
325		case reasoning.KindNamed:
326			effort := string(policy.Value)
327			switch effort {
328			case "minimal", "low", "medium", "high", "xhigh":
329			default:
330				return fmt.Errorf("unsupported OpenRouter effort %q", effort)
331			}
332			body["reasoning"] = map[string]interface{}{"effort": effort}
333		case reasoning.KindTokens:
334			body["reasoning"] = map[string]interface{}{"max_tokens": policy.Tokens}
335		default:
336			return fmt.Errorf("unsupported policy kind %q for openrouter wire", policy.Kind)
337		}
338		return nil
339	}
340	
341	func addQwenFields(body map[string]interface{}, policy reasoning.Policy) error {
342		if policy.Kind == reasoning.KindOff {
343			body["enable_thinking"] = false
344			body["thinking_budget"] = 0
345			return nil
346		}
347		budget, err := reasoning.BudgetFor(policy, nil, 0)
348		if err != nil {
349			return err
350		}
351		if budget <= 0 {
352			body["enable_thinking"] = false
353			body["thinking_budget"] = 0
354			return nil
355		}
356		body["enable_thinking"] = true
357		body["thinking_budget"] = budget
358		return nil
359	}
