383	// parseResponse extracts finish_reason, reasoning_tokens, and <think> hash
384	// from a raw chat-completion response body.
385	func parseResponse(raw []byte, r *probeResult) {
386		var resp struct {
387			Choices []struct {
388				FinishReason string `json:"finish_reason"`
389				Message      struct {
390					Content string `json:"content"`
391				} `json:"message"`
392			} `json:"choices"`
393			Usage json.RawMessage `json:"usage"`
394		}
395		if err := json.Unmarshal(raw, &resp); err != nil {
396			r.Error = fmt.Sprintf("parse response json: %v", err)
397			return
398		}
399		if len(resp.Choices) > 0 {
400			r.FinishReason = resp.Choices[0].FinishReason
401			content := resp.Choices[0].Message.Content
402			if m := thinkRe.FindStringSubmatch(content); len(m) > 1 {
403				sum := sha256.Sum256([]byte(m[1]))
404				r.ThinkHash = fmt.Sprintf("%x", sum[:8])
405			}
406		}
407		if len(resp.Usage) > 0 {
408			r.ReasoningToks = extractReasoningTokens(string(resp.Usage))
409		}
410	}
