496	// allWithinPct returns true if all values in vs are within pct% of their mean.
497	func allWithinPct(vs []int, pct float64) bool {
498		if len(vs) == 0 {
499			return true
500		}
501		nonZero := 0
502		sum := 0
503		for _, v := range vs {
504			if v > 0 {
505				nonZero++
506				sum += v
507			}
508		}
509		if nonZero == 0 {
510			return true
511		}
512		mean := float64(sum) / float64(nonZero)
513		for _, v := range vs {
514			if v == 0 {
515				continue
516			}
517			if math.Abs(float64(v)-mean)/mean*100 > pct {
518				return false
519			}
520		}
521		return true
522	}
523	
524	// budgetsDifferProportionally returns true when the ratio of observed reasoning
525	// tokens for two different budgets is within tolerancePct% of the ratio of the
526	// requested budgets. E.g. budget 16384 should produce ~4x the tokens of 4096.
527	func budgetsDifferProportionally(toks1, toks2, budget1, budget2 int, tolerancePct float64) bool {
528		if toks1 <= 0 || toks2 <= 0 {
529			return false
530		}
531		expectedRatio := float64(budget2) / float64(budget1)
532		observedRatio := float64(toks2) / float64(toks1)
533		// Within tolerancePct% of expected ratio.
534		return math.Abs(observedRatio-expectedRatio)/expectedRatio*100 <= tolerancePct
535	}
